export function Filters({ setVille }) {
  return (
    <div className="mb-4 flex gap-4">
      <input
        type="text"
        placeholder="Filtrer par ville"
        onChange={(e) => setVille(e.target.value)}
        className="border px-2 py-1 rounded"
      />
    </div>
  );
}
